<div class="form-section"><div class="form-section__heading"><span class="eyebrow">Customer</span><h3>Profile details</h3></div><div class="form-grid"><div class="field field--span-2"><label>Name</label><input name="name" value="<?=e($data['name'])?>" maxlength="150" required autofocus><?php if(isset($errors['name'])):?><small class="field-error"><?=e($errors['name'])?></small><?php endif;?></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($data['phone'])?>" maxlength="50"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($data['email'])?>" maxlength="150"><?php if(isset($errors['email'])):?><small class="field-error"><?=e($errors['email'])?></small><?php endif;?></div><div class="field field--span-2"><label>Address</label><input name="address" value="<?=e($data['address'])?>" maxlength="255"></div><div class="field"><label>Credit limit</label><input type="number" name="credit_limit" min="0" step="0.01" value="<?=e($data['credit_limit'])?>"></div><div class="field"><label>Status</label><select name="status"><option value="active" <?=$data['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$data['status']==='inactive'?'selected':''?>>Inactive</option></select></div><div class="field field--span-2"><label>Notes</label><textarea name="notes" rows="4"><?=e($data['notes'])?></textarea></div></div></div>
